// ===== TEST SCENARIO SWITCH ====================================================
// Keep the name SCENARIO; change the value. Save, run.
// Options: improving | plateau | declining_safety | fast_and_sloppy | first_session
const SCENARIO = "declining_safety";
// Integration: the entry trigger passes the real case_file and skips this node.
// ==============================================================================
const SCENARIOS = {"improving":{"prescription":{"exercise":"elbow_flexion","target_reps":10,"target_rom":120},"metrics":{"reps_vs_target_pct":100,"rom_vs_target_pct":87,"fault_counts":{},"fast_rep_share":0,"rom_slope_deg_per_session":1.87,"baseline_rom":102,"quality_band":"good","incomplete_attempts":0,"sessions_in_history":8},"rule_flags":[]},"plateau":{"prescription":{"exercise":"elbow_flexion","target_reps":10,"target_rom":120},"metrics":{"reps_vs_target_pct":100,"rom_vs_target_pct":83,"fault_counts":{},"fast_rep_share":0,"rom_slope_deg_per_session":0,"baseline_rom":100,"quality_band":"good","incomplete_attempts":0,"sessions_in_history":8},"rule_flags":[]},"declining_safety":{"prescription":{"exercise":"elbow_flexion","target_reps":10,"target_rom":120},"metrics":{"reps_vs_target_pct":100,"rom_vs_target_pct":71,"fault_counts":{"SHOULDER_HIKE":3},"fast_rep_share":0,"rom_slope_deg_per_session":-3.46,"baseline_rom":92.3,"quality_band":"fair","incomplete_attempts":0,"sessions_in_history":7},"rule_flags":[{"code":"NEW_COMPENSATION","severity":"medium","source":"rule","evidence":"SHOULDER_HIKE not seen in history"}]},"fast_and_sloppy":{"prescription":{"exercise":"elbow_flexion","target_reps":10,"target_rom":120},"metrics":{"reps_vs_target_pct":100,"rom_vs_target_pct":85,"fault_counts":{"TOO_FAST":3},"fast_rep_share":1,"rom_slope_deg_per_session":0.7,"baseline_rom":101,"quality_band":"fair","incomplete_attempts":0,"sessions_in_history":3},"rule_flags":[{"code":"NEW_COMPENSATION","severity":"medium","source":"rule","evidence":"TOO_FAST not seen in history"},{"code":"RUSHED_REPS","severity":"low","source":"rule","evidence":"majority of reps too fast"}]},"first_session":{"prescription":{"exercise":"elbow_flexion","target_reps":10,"target_rom":120},"metrics":{"reps_vs_target_pct":100,"rom_vs_target_pct":79,"fault_counts":{},"fast_rep_share":0,"rom_slope_deg_per_session":null,"baseline_rom":null,"quality_band":"good","incomplete_attempts":0,"sessions_in_history":0},"rule_flags":[]}};
return [{ json: { case_file: SCENARIOS[SCENARIO] } }];

// CODE sets the trend verdict from the slope (not the model).
const input = $input.first().json || {};
const cf = input.case_file || input;
const m = (cf && cf.metrics) || {};
const slope = m.rom_slope_deg_per_session;
const sessions = (m.sessions_in_history != null) ? m.sessions_in_history : 0;
let trend;
if (slope === null || slope === undefined || sessions < 2) trend = "insufficient_data";
else if (slope > 0.5)  trend = "improving";
else if (slope < -0.5) trend = "declining";
else                   trend = "stable";
return [{ json: { case_file: cf, trend } }];

