// Recover case_file + trend (the agent output dropped them) and attach assessment.
const base = $('Set Trend (code)').first().json;
const assessment = $input.first().json.output ?? $input.first().json;
return [{ json: { case_file: base.case_file, trend: base.trend, assessment } }];

const prev = $('Collect Assessment').first().json;
const progress = $input.first().json.output ?? $input.first().json;
return [{ json: { ...prev, progress } }];

// STUB for Person B's Coaching agent (code, not an agent — no nesting).
const prev = $input.first().json;
return [{ json: { ...prev, coaching: {
  patient_message: "Nice work finishing your set today. Keep your shoulder relaxed and move slowly and smoothly. Your physiotherapist will review your progress.",
  cue_ids: ["cue_shoulder_down","cue_slow_down"], rounds_used: 1, status: "pending_review"
} } }];

// STUB for Person B's Safety agent.
const prev = $input.first().json;
return [{ json: { ...prev, review: { verdict:"approve", issues:[], extra_flags:[] } } }];

// A6 — assemble the merged result + a simple pipeline trace (no tool calls now).
const d = $input.first().json;
const line = (o)=> JSON.stringify(o ?? {}).slice(0,160);
const agent_trace = [
  { step:1, from:"pipeline", to:"get_case_file", message:"load case file", reply_summary: line(d.case_file && d.case_file.metrics) },
  { step:2, from:"pipeline", to:"set_trend",     message:"compute trend",   reply_summary: "trend="+d.trend },
  { step:3, from:"pipeline", to:"assessment",    message:"assess quality",  reply_summary: line(d.assessment) },
  { step:4, from:"pipeline", to:"progress",      message:"trend + new/worsening faults", reply_summary: line(d.progress) },
  { step:5, from:"pipeline", to:"coaching",      message:"draft patient message", reply_summary: line(d.coaching) },
  { step:6, from:"pipeline", to:"safety",        message:"review coaching",  reply_summary: line(d.review) },
];
return [{ json: {
  supervisor_summary: `Quality ${d.assessment ? d.assessment.quality_band : "?"}, trend ${d.trend}; coaching ${d.review ? d.review.verdict : "?"}d (pending physio review).`,
  agent_trace,
  calls_per_agent: { assessment:1, progress:1, coaching:1, safety:1 },
  assessment: d.assessment, progress: d.progress, coaching: d.coaching, review: d.review,
  case_file: d.case_file, trend: d.trend
} }];
